class Solution:
    def maxSumOfThreeSubarrays(self, nums: list[int], k: int) -> list[int]:
        n = len(nums)
        prefix = [0]
        for x in nums:
            prefix.append(prefix[-1] + x)
        def window(i):
            return prefix[i + k] - prefix[i]
        best_sum = -1
        ans = []
        for mid in range(k, n - 2 * k + 1):
            best_left_sum = -1
            best_left = 0
            for left in range(0, mid - k + 1):
                s = window(left)
                if s > best_left_sum:
                    best_left_sum = s
                    best_left = left
            best_right_sum = -1
            best_right = mid + k
            for right in range(mid + k, n - k + 1):
                s = window(right)
                if s > best_right_sum:
                    best_right_sum = s
                    best_right = right
            total = best_left_sum + window(mid) + best_right_sum
            cand = [best_left, mid, best_right]
            if total > best_sum or (total == best_sum and cand < ans):
                best_sum = total
                ans = cand
        return ans

